CREATE SCHEMA IF NOT EXISTS operations;
CREATE SCHEMA IF NOT EXISTS certificates;
CREATE SCHEMA IF NOT EXISTS integration;
CREATE TABLE IF NOT EXISTS operations.report_jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,requested_by uuid NOT NULL,event_id text NOT NULL,scope text NOT NULL,format text NOT NULL CHECK(format IN ('csv','json')),status text NOT NULL CHECK(status IN ('pending','running','succeeded','failed','cancelled','expired','purged')),progress int NOT NULL DEFAULT 0,artifact_key text,artifact_sha256 text,error_code text,watermark timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '1 day',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS certificates.certificates(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,event_id text NOT NULL,registration_id text NOT NULL,verification_code text NOT NULL UNIQUE,display_name text NOT NULL,state text NOT NULL CHECK(state IN ('issued','revoked','replaced')),artifact_key text NOT NULL,artifact_sha256 text NOT NULL,issued_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS integration.hukid_configs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,issuer_id text NOT NULL,credential_definition text NOT NULL,base_url text NOT NULL,oauth_url text NOT NULL,status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS integration.hukid_deliveries(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,certificate_id uuid NOT NULL REFERENCES certificates.certificates(id),config_id uuid NOT NULL REFERENCES integration.hukid_configs(id),idempotency_key text NOT NULL,source_reference text NOT NULL,state text NOT NULL CHECK(state IN ('pending','request_created','offer_redeemed','credential_issued','failed','cancelled')),hukid_request_id text,credential_offer_uri text,credential_id text,last_error_code text,attempts int NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,source_reference),UNIQUE(tenant_id,idempotency_key));
